package main

import (
	"bytes"
	"fmt"
	"go/format"
	"strconv"
	"strings"
)

// header is the banner every generated file carries.
const header = `// Code generated by internal/gen from the HostTracker OpenAPI document. DO NOT EDIT.
//
// Regenerate with ./scripts/regen.sh.
`

// emit renders one group as a Go source file.
func emit(pkg string, g group) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(header)
	fmt.Fprintf(&b, "\npackage %s\n\n", pkg)
	b.WriteString("import \"github.com/HostTracker/cli/internal/htcli\"\n\n")
	b.WriteString("func init() {\n")

	b.WriteString("\thtcli.RegisterGroup(htcli.Group{\n")
	field(&b, 2, "Name", g.Name)
	field(&b, 2, "Tag", g.Tag)
	field(&b, 2, "Short", g.Short)
	if len(g.Aliases) > 0 {
		fmt.Fprintf(&b, "\t\tAliases: %s,\n", stringSlice(g.Aliases))
	}
	b.WriteString("\t})\n")

	for _, cmd := range g.Commands {
		b.WriteString("\n\thtcli.Register(htcli.Operation{\n")
		field(&b, 2, "Group", cmd.Group)
		field(&b, 2, "Name", cmd.Name)
		field(&b, 2, "ID", cmd.ID)
		field(&b, 2, "Method", cmd.Method)
		field(&b, 2, "Path", cmd.Path)
		field(&b, 2, "Summary", cmd.Summary)
		field(&b, 2, "Description", cmd.Description)
		if len(cmd.Args) > 0 {
			b.WriteString("\t\tArgs: []htcli.Arg{\n")
			for _, arg := range cmd.Args {
				fmt.Fprintf(&b, "\t\t\t{Name: %s, Help: %s},\n", quote(arg.Name), quote(arg.Help))
			}
			b.WriteString("\t\t},\n")
		}
		if len(cmd.Params) > 0 {
			b.WriteString("\t\tParams: []htcli.Param{\n")
			for _, param := range cmd.Params {
				b.WriteString("\t\t\t{")
				var parts []string
				parts = append(parts, "Name: "+quote(param.Name))
				parts = append(parts, "Flag: "+quote(param.Flag))
				parts = append(parts, "In: "+quote(param.In))
				parts = append(parts, "Type: "+quote(param.Type))
				if param.Items != "" {
					parts = append(parts, "Items: "+quote(param.Items))
				}
				if len(param.Enum) > 0 {
					parts = append(parts, "Enum: "+stringSlice(param.Enum))
				}
				// Explode only means something for an array.
				if param.Type == "array" && param.Explode {
					parts = append(parts, "Explode: true")
				}
				if param.Required {
					parts = append(parts, "Required: true")
				}
				parts = append(parts, "Help: "+quote(param.Help))
				b.WriteString(strings.Join(parts, ", "))
				b.WriteString("},\n")
			}
			b.WriteString("\t\t},\n")
		}
		if cmd.Body {
			b.WriteString("\t\tBody: true,\n")
		}
		if cmd.BodyRequired {
			b.WriteString("\t\tBodyRequired: true,\n")
		}
		if cmd.QueryPath != "" {
			field(&b, 2, "QueryPath", cmd.QueryPath)
		}
		if cmd.Paged {
			b.WriteString("\t\tPaged: true,\n")
		}
		if cmd.Binary {
			b.WriteString("\t\tBinary: true,\n")
		}
		if cmd.Deprecated != "" {
			field(&b, 2, "Deprecated", cmd.Deprecated)
		}
		b.WriteString("\t})\n")
	}
	b.WriteString("}\n")

	formatted, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("%s: the generated source does not parse: %w", g.Name, err)
	}
	return formatted, nil
}

// emitDoc renders the package comment of the generated package.
func emitDoc(pkg string, groups []group, title, version string) ([]byte, error) {
	commands := 0
	for _, g := range groups {
		commands += len(g.Commands)
	}
	var b bytes.Buffer
	b.WriteString(header)
	fmt.Fprintf(&b, `
// Package %s holds one command per operation of the %s,
// version %s: %d commands in %d groups.
//
// Importing the package registers them; cmd wires the registry onto the
// root command.
package %s
`, pkg, title, version, commands, len(groups), pkg)
	return format.Source(b.Bytes())
}

func field(b *bytes.Buffer, depth int, name, value string) {
	if value == "" {
		return
	}
	fmt.Fprintf(b, "%s%s: %s,\n", strings.Repeat("\t", depth), name, quote(value))
}

func quote(value string) string { return strconv.Quote(value) }

func stringSlice(values []string) string {
	quoted := make([]string, 0, len(values))
	for _, value := range values {
		quoted = append(quoted, quote(value))
	}
	return "[]string{" + strings.Join(quoted, ", ") + "}"
}
